changeSet.sql:
INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'notification.form058-card-linked.enabled', 'true', 'BOOLEAN', 'Notify the sender organization when a Card is linked to a Form058 (ACCEPTED -> CARD_LINKED).', true, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'notification.form058-card-linked.enabled');

INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'notification.form058-approved.enabled', 'true', 'BOOLEAN', 'Notify the receiver organization when a Form058 is given final approval (-> APPROVED).', true, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'notification.form058-approved.enabled');

INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'notification.form058-reopened.enabled', 'true', 'BOOLEAN', 'Notify both organizations when a super-admin reopens a canceled Form058 (CANCELED -> SENT).', true, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'notification.form058-reopened.enabled');

